From bbc5680d0439470cde777212cde1dd2cfeb80227 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:55:17 +0100
Subject: [PATCH] wallpapers/hunyango: update accent color when the color
 changes

The accent color taken from the wallpaper was only computed once, so it
stayed on the first color while Hunyango kept cycling through new ones.
Have it recomputed every time the background settles on a new color.

BUG: 519981
---
 wallpapers/hunyango/contents/ui/ColorProvider.qml | 7 ++++++-
 wallpapers/hunyango/contents/ui/main.qml          | 7 +++++++
 2 files changed, 13 insertions(+), 1 deletion(-)

diff --git a/wallpapers/hunyango/contents/ui/ColorProvider.qml b/wallpapers/hunyango/contents/ui/ColorProvider.qml
index 699f2c5c1..d33fa3130 100644
--- a/wallpapers/hunyango/contents/ui/ColorProvider.qml
+++ b/wallpapers/hunyango/contents/ui/ColorProvider.qml
@@ -12,6 +12,8 @@ Item {
     id: root
     property color color: _randomColor()

+    signal colorReached()
+
     // Intentionally not using standard durations because this is an
     // animated wallpaper - animations shouldn't be disabled and the
     // duration shouldn't be scaled with the user's preferences.
@@ -27,7 +29,10 @@ Item {
             }

             ScriptAction {
-                script: updateColor()
+                script: {
+                    colorReached();
+                    updateColor();
+                }
             }
         }
     }
diff --git a/wallpapers/hunyango/contents/ui/main.qml b/wallpapers/hunyango/contents/ui/main.qml
index 11f6b2e7b..0ef7defc6 100644
--- a/wallpapers/hunyango/contents/ui/main.qml
+++ b/wallpapers/hunyango/contents/ui/main.qml
@@ -20,6 +20,13 @@ WallpaperItem {
         }
     ]

+    Connections {
+        target: ColorProvider
+        function onColorReached() {
+            root.accentColorChanged();
+        }
+    }
+
     Rectangle {
         id: rectangle
         anchors.fill: parent
-- 
